<?php require_once __DIR__.'/../includes/bootstrap.php'; require_login(); $uid=(int)(current_user()['id']??0); if(is_admin()){$albums=$pdo->query("SELECT a.*,COUNT(t.id) track_count,u.username owner_username,u.display_name owner_display_name FROM albums a LEFT JOIN tracks t ON t.album_id=a.id LEFT JOIN users u ON u.id=a.owner_user_id GROUP BY a.id ORDER BY a.created_at DESC")->fetchAll();}else{$q=$pdo->prepare('SELECT a.*,COUNT(t.id) track_count FROM albums a LEFT JOIN tracks t ON t.album_id=a.id LEFT JOIN album_collaborators ac ON ac.album_id=a.id AND ac.user_id=? WHERE a.owner_user_id=? OR ac.user_id IS NOT NULL GROUP BY a.id ORDER BY a.created_at DESC');$q->execute([$uid,$uid]);$albums=$q->fetchAll();} render_header('Alben',true); ?><div class="d-flex justify-content-between align-items-center mb-4"><div><h1 class="h2 mb-1">Alben</h1><p class="text-body-secondary mb-0">Musikalben hochladen, gestalten und teilen.</p></div><a class="btn btn-primary" href="album_edit.php">Neues Album</a></div><div class="row g-4"><?php foreach($albums as $a):?><div class="col-sm-6 col-lg-4"><div class="card h-100 shadow-sm"><?php if($a['cover_file']):?><a href="album_edit.php?id=<?=$a['id']?>" aria-label="Album <?=e($a['title'])?> verwalten"><img src="<?=base_url('uploads/covers/'.$a['cover_file'])?>" class="card-img-top" style="aspect-ratio:1/1;object-fit:cover" alt="Cover von <?=e($a['title'])?>"></a><?php else:?><a href="album_edit.php?id=<?=$a['id']?>" class="text-decoration-none" aria-label="Album <?=e($a['title'])?> verwalten"><div class="cover-placeholder rounded-0">♪</div></a><?php endif?><div class="card-body"><h2 class="h5"><?=e($a['title'])?></h2><p class="text-body-secondary mb-2"><?=e($a['artist'])?> · <?=$a['track_count']?> Titel</p><?php if(is_admin()):$isOwn=(int)$a['owner_user_id']===$uid;?><div class="small mb-3"><span class="badge <?=$isOwn?'text-bg-secondary':'text-bg-info'?>"><?=$isOwn?'Eigenes Album':'Fremdes Album'?></span><span class="text-body-secondary ms-2">Erstellt von <?=e($a['owner_display_name']?:$a['owner_username']?:'Unbekannt')?></span></div><?php endif?><div class="d-flex gap-2"><a class="btn btn-sm btn-primary" href="album_edit.php?id=<?=$a['id']?>">Verwalten</a><a class="btn btn-sm btn-outline-secondary" target="_blank" href="<?=base_url('share.php?album_id='.$a['id'])?>">Vorschau</a></div></div></div></div><?php endforeach?><?php if(!$albums):?><div class="col-12"><div class="alert alert-info">Noch keine Alben vorhanden.</div></div><?php endif?></div><?php render_footer();
